        return Geometry.Parse("M12 2L15 8L21 9L17 14L18 20L12 17L6 20L7 14L3 9L9 8L12 2Z");
    }

    public static Geometry? GetGeometry(string providerName)
    {
        if (Enum.TryParse<Provider>(providerName, true, out var prov))
        {
            return GetGeometry(prov);
        }

        if (_rawPaths.TryGetValue(providerName, out var raw))
        {
            try
            {
                var geom = Geometry.Parse(raw);
                geom.Freeze();
                return geom;
            }
            catch { }
        }

        return Geometry.Parse("M12 2L15 8L21 9L17 14L18 20L12 17L6 20L7 14L3 9L9 8L12 2Z");
    }
}
